-- Borean Tundra: creature abilities
-- Most of the zone's creatures (the Scourge, the Kvaldir, the Blue Dragonflight, the Taunka and tuskarr's foes, the Nerubians and
-- wildlife) had no AI or ran classic rows: port their abilities from the classic (AzerothCore) data, falling back to the Cataclysm
-- data; rows needing events, actions or action lists LoA lacks are left out, and AzerothCore's range and area events are converted.
-- The creatures no reference scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '24957,25209,25211,25226,25227,25242,25243,25294,25311,25383,25386,25393,25415,25417,25419,25427,25428,25445,25454,25464,25465,25467,25468,25479,25496,25498,25514,25520,25523,25584,25596,25600,25601,25609,25613,25615,25619,25622,25623,25678,25684,25685,25686,25687,25699,25701,25709,25712,25716,25717,25719,25720,25722,25752,25764,25774,25789,25800,25801,25803,25844,25981,26094,26103,26202,26266,26449,26451,26452,27106,27107,27108,27110,32534';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '24765,25244,25338,25351,25387,25446,25451,25453,25481,25521,25522,25660,25725,26115,27073,27189,51877,51889';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
